targets.expr:
max by (namespace, created_by_name) (
  kube_pod_start_time
  * on(namespace, pod) group_left(created_by_name)
  kube_pod_info{created_by_kind="StatefulSet", created_by_name=~"${game}-a$|${game}-b$", namespace="${namespace}"}
) * 1000

max(
    sum by (created_by_name) (
        kube_pod_info{namespace="${namespace}", created_by_kind="StatefulSet", created_by_name=~"${game}-(a|b)$"}
        and on(pod, namespace)
        kube_pod_status_phase{namespace="${namespace}", phase="Running"}
    ) > 0
) by (created_by_name)

count(
    sum by (created_by_name) (
        kube_pod_info{namespace="${namespace}", created_by_kind="StatefulSet", created_by_name=~"${game}-(a|b)$"}
        and on(pod, namespace)
        kube_pod_status_phase{phase="Running"}
    ) > 0
)

sum(
  # 获取StatefulSet的CPU使用率总和
  sum by(pod) (rate(container_cpu_usage_seconds_total{namespace="$namespace",container!="",image!="",container!="POD"}[5m]))
  * on(pod) group_left(created_by_name)
  kube_pod_info{namespace="$namespace", created_by_kind="StatefulSet", created_by_name="$statefulset"}
)
/
# 获取该StatefulSet的CPU请求总和
sum(
  kube_pod_container_resource_requests{resource="cpu",namespace="$namespace"}
  * on(pod) group_left(created_by_name)
  kube_pod_info{namespace="$namespace", created_by_kind="StatefulSet", created_by_name="$statefulset"}
)

sum(
  # 获取StatefulSet的CPU使用率总和
  sum by(pod) (rate(container_cpu_usage_seconds_total{namespace="$namespace",container!="",image!="",container!="POD"}[5m]))
  * on(pod) group_left(created_by_name)
  kube_pod_info{namespace="$namespace", created_by_kind="StatefulSet", created_by_name="$statefulset"}
)
/
# 获取该StatefulSet的CPU限制总和
sum(
  kube_pod_container_resource_limits{resource="cpu",namespace="$namespace"}
  * on(pod) group_left(created_by_name)
  kube_pod_info{namespace="$namespace", created_by_kind="StatefulSet", created_by_name="$statefulset"}
)

# 获取该StatefulSet的内存使用总量
sum (
    sum by(pod) (
    container_memory_working_set_bytes{namespace="$namespace",container!="",image!="",container!="POD"} 
    * on(pod) group_left(created_by_name)
    kube_pod_info{namespace="$namespace", created_by_kind="StatefulSet", created_by_name="$statefulset"}
    )
)
/
sum(
  group (kube_pod_info{namespace="$namespace", created_by_kind="StatefulSet", created_by_name="$statefulset"}) by (pod)
  * on(pod) 
  max by (pod) (kube_pod_container_resource_requests{resource="memory", namespace="$namespace"})
)

# 获取该StatefulSet的内存使用总量
sum (
    sum by(pod) (
    container_memory_working_set_bytes{namespace="$namespace",container!="",image!="",container!="POD"} 
    * on(pod) group_left(created_by_name)
    kube_pod_info{namespace="$namespace", created_by_kind="StatefulSet", created_by_name="$statefulset"}
    )
)
/
sum(
  group (kube_pod_info{namespace="$namespace", created_by_kind="StatefulSet", created_by_name="$statefulset"}) by (pod)
  * on(pod) 
  max by (pod) (kube_pod_container_resource_limits{resource="memory", namespace="$namespace"})
)

max(group(kube_pod_info{namespace="$namespace",created_by_kind="StatefulSet",pod_ip!="", created_by_name="$statefulset"}) by (pod)
    * on(pod) group_right() max(kube_pod_container_resource_limits{resource="cpu",namespace="$namespace"}) by (pod, container,image) 
) by (container)
